base=Path(__file__).resolve().parents[1];tree=ast.parse((base/'scripts/validate-war-scouter.py').read_text());setup=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='setup' for t in n.targets));bundle=(base/'dist/tu-integrated-staging-dev.user.js').read_text();out=base.parent/'development/evidence/hospitalization-recovery-117';out.mkdir(parents=True,exist_ok=True)
seed=r'''window.events=[];document.addEventListener('tu-snatch-run-diagnostic',e=>events.push(JSON.parse(e.detail)));localStorage.setItem('tu-item-monitor-v1',JSON.stringify([{key:'id:206',name:'Xanax',category:'Foreign',minQty:1}]));sessionStorage.setItem('tu:snatch-run:v1',JSON.stringify({ownerId:'42',country:'jap',intentId:'synthetic-landing',watchKey:'id:206',watchName:'Xanax',minimumQty:1,planHospitalize:true,hospital:true,hospitalization:{id:3,name:'Synthetic hospital item'},hospitalizations:[{id:3,name:'Synthetic hospital item'}],stage:'hospitalize',stockAt:0,hospitalizationAttempted:false,hospitalizedConfirmed:false}));document.body.innerHTML='<main id="travel-root"><h4>Traveling</h4><section aria-label="Flight progress">Torn to Japan. Remaining Flight Time - 00:00:05</section></main>';void 0;'''
