with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 try:
  for label,width,height in [('desktop',1280,900),('portrait',390,844),('landscape',844,390)]:
   ctx=browser.new_context(viewport={'width':width,'height':height},is_mobile=label!='desktop',has_touch=label!='desktop');ctx.route('**/*',lambda r:r.fulfill(content_type='text/html',body='<meta name="viewport" content="width=device-width,initial-scale=1"><body></body>'));page=ctx.new_page();page.goto('https://www.torn.com/index.php');page.evaluate(setup);page.evaluate(seed);page.evaluate(bundle);page.wait_for_function('TornUtilities.isAuthorized()');page.locator('#tu-pda-launcher').click();page.locator('[data-tab=modules]').click()
   for name in ['Business Tools','Travel Assistant and Item Monitor']:page.locator('.tu-card').filter(has=page.get_by_text(name,exact=True)).locator('button').click()
   button=page.locator('#tu-snatch-run');page.wait_for_function("document.querySelector('#tu-snatch-run')?.dataset.snatchStage==='hospitalize'");page.evaluate(land);page.wait_for_function("document.querySelector('#tu-snatch-run').dataset.snatchStage==='waiting'");page.evaluate("document.getElementById('fixture-hospital').remove();window.dispatchEvent(new Event('focus'));void 0;");page.wait_for_function("document.querySelector('#tu-snatch-run').dataset.snatchStage==='hospitalize'&&document.querySelector('#tu-snatch-run').getAttribute('aria-disabled')==='false'");assert page.evaluate("events.filter(e=>e.event==='action-start').length")==0;assert page.evaluate("events.filter(e=>e.event==='hospitalize-restored').length")==1;page.evaluate("window.TUWindowNavigation?.minimize('tuim-menu');void 0;");assert button.is_visible();page.screenshot(path=str(out/(label+'-recovered.png')));ctx.close()
  (out/'validation.json').write_text(json.dumps({'build':'0.5.42.117-dev','synthetic_only':True,'viewports':['desktop','portrait','landscape'],'checks':['outbound flight','transient hospital indicator during foreign-page transition','hospitalization plan suspended','non-hospitalized abroad restores ready Hospitalize','one recovery event','zero gameplay action starts']},indent=2)+'\n');print('Generated .117 hospitalization recovery passed desktop, portrait and landscape; no gameplay actions.')
 finally:browser.close()
